#define PI 3.1415
//https://www.shadertoy.com/view/3tdSDj
float udSegment( in vec2 p, in vec2 a, in vec2 b )
{
    vec2 ba = b-a;
    vec2 pa = p-a;
    float h =clamp( dot(pa,ba)/dot(ba,ba), 0.0, 1.0 );
    return length(pa-h*ba);
}

mat2 rotate(float a) {
	return mat2(cos(a), -sin(a), sin(a), cos(a));
}


void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = ( 2. * fragCoord - iResolution.xy ) / iResolution.y; 

    float steps = 200.0;  
    float dist = 0.04;    
    float minThickness = 0.001;

    float time = iTime * 0.5;            
    float freq = 8.0;
    float amp = 1.;

    vec2 position = vec2(0.0, -1.0);  
    vec2 direction = vec2(0.0, 1.0); 

    float lineDistance = 1e9;

    for (float i = 0.0; i < steps; i++) {
        float n = i / steps;
        float thickness = minThickness + (1. - n) * 0.01;
        float sinValue = sin(time + n * PI * freq) * amp;

        direction = rotate(sinValue * n) * direction;

        vec2 start = position;
        position += direction * dist;

        float segment = udSegment(uv, start, position) - thickness;
        lineDistance = min(lineDistance, segment); 
    } 

    vec3 color = vec3(1. - lineDistance * iResolution.y / 3.); //aa
    fragColor = vec4(color, 1.0);
}
